// Edit these settings.
// ollamaUrl: where n8n can reach Ollama. In Docker on the same machine, use http://host.docker.internal:11434
// expectedModels: the models you pulled yourself. Leave the list empty to skip the model check.
return [{
  json: {
    ollamaUrl: 'http://localhost:11434',
    expectedModels: ['llama3.2:3b', 'nomic-embed-text'],
  },
}];

// Compares what the server reports with the latest release, OSV.dev and your model list.
const settings = $('Settings').first().json;
const versionAnswer = $('Get Ollama version').first().json;
const tagsAnswer = $('List installed models').first().json;
const releaseAnswer = $('Get latest Ollama release').first().json;
const osvAnswer = $input.first().json;

function parts(v) {
  let s = String(v || '').trim();
  if (s.startsWith('v')) s = s.slice(1);
  const out = [];
  for (const piece of s.split('.')) {
    const n = parseInt(piece, 10);
    if (isNaN(n)) break;
    out.push(n);
    if (String(n) !== piece) break;
  }
  return out;
}

function cmp(a, b) {
  const x = parts(a);
  const y = parts(b);
  for (let i = 0; i < Math.max(x.length, y.length); i++) {
    const d = (x[i] || 0) - (y[i] || 0);
    if (d !== 0) return d > 0 ? 1 : -1;
  }
  return 0;
}

// 'llama3.2:latest' and 'llama3.2' are the same model.
function modelName(n) {
  const s = String(n || '').trim().toLowerCase();
  return s.endsWith(':latest') ? s.slice(0, -7) : s;
}

const lines = [];
const installed = versionAnswer.error ? null : versionAnswer.version;

if (!installed) {
  lines.push('Ollama did not answer at ' + settings.ollamaUrl + '. Is it running, and can n8n reach it?');
} else {
  let latest = releaseAnswer.error ? null : String(releaseAnswer.tag_name || '');
  if (latest && latest.startsWith('v')) latest = latest.slice(1);
  if (latest && cmp(latest, installed) > 0) {
    lines.push('Update available: this server runs ' + installed + ', the latest release is ' + latest + '. ' + (releaseAnswer.html_url || ''));
  }
  const vulns = osvAnswer.error ? [] : (osvAnswer.vulns || []);
  if (vulns.length) {
    lines.push(vulns.length + ' published advisories affect Ollama ' + installed + ':');
    for (const v of vulns.slice(0, 10)) {
      lines.push('- ' + v.id + ': ' + (v.summary || 'no summary') + ' https://osv.dev/vulnerability/' + v.id);
    }
    if (vulns.length > 10) lines.push('- and ' + (vulns.length - 10) + ' more');
  }
  if (osvAnswer.error) lines.push('OSV.dev could not be reached, so advisories were not checked today.');
}

const expected = (settings.expectedModels || []).map(modelName);
if (!tagsAnswer.error && Array.isArray(tagsAnswer.models) && expected.length) {
  const names = tagsAnswer.models.map(m => m.name);
  const present = names.map(modelName);
  const unexpected = names.filter(n => !expected.includes(modelName(n)));
  const missing = expected.filter(e => !present.includes(e));
  if (unexpected.length) {
    lines.push('Models you did not list: ' + unexpected.join(', ') + '. If nobody on your side pulled them, someone else may be using this server. Make sure port 11434 is not reachable from the internet.');
  }
  if (missing.length) lines.push('Expected models that are gone: ' + missing.join(', ') + '.');
}

let sizeNote = '';
if (!tagsAnswer.error && Array.isArray(tagsAnswer.models)) {
  const bytes = tagsAnswer.models.reduce((n, m) => n + (Number(m.size) || 0), 0);
  sizeNote = tagsAnswer.models.length + ' models installed, ' + (bytes / 1e9).toFixed(1) + ' GB in total.';
}

const header = 'Ollama check for ' + settings.ollamaUrl;
const message = [header, ''].concat(lines, sizeNote ? ['', sizeNote] : []).join('\n');

return [{ json: { alert: lines.length > 0, findings: lines.length, message } }];
